{"file_path":"src/address.js","content":"/**
 * Column and address arithmetic. Columns run A..Z then AA..ZZ, encoded as
 * base-26 numbers 1..702 (A=1); rows are 1..999.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

export function colToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse an already upper-cased address token. Returns null when it is not
 * in the addressable range (wrong letter/digit counts, or row 0).
 */
export function parseAddress(text) {
  const m = ADDRESS_RE.exec(text)
  if (!m) return null
  const col = colToNum(m[1])
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col, row, key: col * 1000 + row }
}

export function keyToAddress(key) {
  const row = key % 1000
  const col = (key - row) / 1000
  return numToCol(col) + String(row)
}

export function makeKey(col, row) {
  return col * 1000 + row
}
"}

