{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const NUMBER_RE = /^\d+(\.\d+)?/
const IDENT_RE = /^[A-Za-z]+[0-9]*/

export class LexError extends Error {}

export function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    const rest = src.slice(i)
    let m
    if ((m = NUMBER_RE.exec(rest))) {
      tokens.push({ type: 'NUM', text: m[0] })
      i += m[0].length
      continue
    }
    if ((m = IDENT_RE.exec(rest))) {
      tokens.push({ type: 'IDENT', text: m[0] })
      i += m[0].length
      continue
    }
    if (rest.startsWith('<=')) {
      tokens.push({ type: 'OP', text: '<=' })
      i += 2
      continue
    }
    if (rest.startsWith('>=')) {
      tokens.push({ type: 'OP', text: '>=' })
      i += 2
      continue
    }
    if (rest.startsWith('<>')) {
      tokens.push({ type: 'OP', text: '<>' })
      i += 2
      continue
    }
    if ('=<>+-*/^'.includes(ch)) {
      tokens.push({ type: 'OP', text: ch })
      i += 1
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN', text: ch })
      i += 1
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN', text: ch })
      i += 1
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA', text: ch })
      i += 1
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON', text: ch })
      i += 1
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  tokens.push({ type: 'EOF', text: '' })
  return tokens
}
"}

