{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Produces a small AST or
 * throws ParseError, which the caller turns into `#ERR!`.
 */

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (t.type !== type) throw new ParseError(`expected ${type}, got ${t.type}`)
    return t
  }
}

function parseComparison(ts) {
  let left = parseAdditive(ts)
  for (;;) {
    const t = ts.peek()
    if (t.type === 'OP' && COMPARE_OPS.has(t.text)) {
      ts.next()
      const right = parseAdditive(ts)
      left = { t: 'bin', op: t.text, l: left, r: right }
    } else break
  }
  return left
}

function parseAdditive(ts) {
  let left = parseMultiplicative(ts)
  for (;;) {
    const t = ts.peek()
    if (t.type === 'OP' && (t.text === '+' || t.text === '-')) {
      ts.next()
      const right = parseMultiplicative(ts)
      left = { t: 'bin', op: t.text, l: left, r: right }
    } else break
  }
  return left
}

function parseMultiplicative(ts) {
  let left = parsePower(ts)
  for (;;) {
    const t = ts.peek()
    if (t.type === 'OP' && (t.text === '*' || t.text === '/')) {
      ts.next()
      const right = parsePower(ts)
      left = { t: 'bin', op: t.text, l: left, r: right }
    } else break
  }
  return left
}

function parsePower(ts) {
  const left = parseUnary(ts)
  const t = ts.peek()
  if (t.type === 'OP' && t.text === '^') {
    ts.next()
    const right = parsePower(ts)
    return { t: 'bin', op: '^', l: left, r: right }
  }
  return left
}

function parseUnary(ts) {
  const t = ts.peek()
  if (t.type === 'OP' && (t.text === '-' || t.text === '+')) {
    ts.next()
    const x = parseUnary(ts)
    return { t: 'un', op: t.text, x }
  }
  return parsePrimary(ts)
}

const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

function parsePrimary(ts) {
  const t = ts.peek()
  if (t.type === 'NUM') {
    ts.next()
    return { t: 'num', v: Number(t.text) }
  }
  if (t.type === 'LPAREN') {
    ts.next()
    const inner = parseComparison(ts)
    ts.expect('RPAREN')
    return inner
  }
  if (t.type === 'IDENT') {
    ts.next()
    const upper = t.text.toUpperCase()
    if (ts.peek().type === 'LPAREN') {
      ts.next()
      const args = parseArgList(ts)
      ts.expect('RPAREN')
      return { t: 'call', name: upper, args }
    }
    if (upper === 'TRUE') return { t: 'bool', v: true }
    if (upper === 'FALSE') return { t: 'bool', v: false }
    return { t: 'addr', text: upper }
  }
  throw new ParseError(`unexpected token ${t.type}`)
}

function parseArgList(ts) {
  const args = [parseArgument(ts)]
  while (ts.peek().type === 'COMMA') {
    ts.next()
    args.push(parseArgument(ts))
  }
  return args
}

function parseArgument(ts) {
  const t = ts.peek()
  if (t.type === 'IDENT') {
    const next = ts.tokens[ts.pos + 1]
    if (next && next.type === 'COLON') {
      const a = ts.next().text.toUpperCase()
      ts.next() // colon
      const b = ts.expect('IDENT').text.toUpperCase()
      return { t: 'range', a, b }
    }
  }
  return parseComparison(ts)
}

/**
 * Parse a formula body (without the leading `=`). Returns the AST, or null
 * when the body is not accepted by the grammar.
 */
export function parseFormula(body) {
  try {
    const tokens = tokenize(body)
    const ts = new TokenStream(tokens)
    const ast = parseComparison(ts)
    ts.expect('EOF')
    return ast
  } catch (e) {
    if (e instanceof ParseError || e instanceof LexError) return null
    throw e
  }
}

export { FUNCTIONS }
"}

