{"file_path":"src/values.js","content":"/**
 * Runtime value representation: a number, text, a boolean, or an error.
 */

export const num = (v) => ({ type: 'number', value: v })
export const text = (v) => ({ type: 'text', value: v })
export const bool = (v) => ({ type: 'bool', value: v })
export const err = (code) => ({ type: 'error', value: code })

export const ERR_DIV0 = '#DIV/0!'
export const ERR_REF = '#REF!'
export const ERR_VALUE = '#VALUE!'
export const ERR_CYCLE = '#CYCLE!'
export const ERR_NAME = '#NAME?'
export const ERR_ERR = '#ERR!'

export const ERROR_TOKENS = new Set([ERR_DIV0, ERR_REF, ERR_VALUE, ERR_CYCLE, ERR_NAME, ERR_ERR])

/** Read a value as a number: booleans coerce, text and errors do not. */
export function toNumber(v) {
  if (v.type === 'number') return { ok: true, num: v.value }
  if (v.type === 'bool') return { ok: true, num: v.value ? 1 : 0 }
  if (v.type === 'error') return { ok: false, err: v }
  return { ok: false, err: err(ERR_VALUE) }
}

function kind(v) {
  return v.type === 'number' ? 0 : v.type === 'text' ? 1 : 2
}

/** Compare two non-error values, returning -1, 0 or 1. */
export function compareValues(l, r) {
  const kl = kind(l)
  const kr = kind(r)
  if (kl !== kr) return kl < kr ? -1 : 1
  if (l.type === 'number' || l.type === 'text') {
    return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  }
  const lv = l.value ? 1 : 0
  const rv = r.value ? 1 : 0
  return lv < rv ? -1 : lv > rv ? 1 : 0
}

export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(v) {
  if (v.type === 'number') return formatNumber(v.value)
  if (v.type === 'error') return v.value
  if (v.type === 'bool') return v.value ? 'TRUE' : 'FALSE'
  return v.value
}
"}

