{"file_path":"src/sheet.js","content":"/**
 * Parses the sheet text format into a map of declared cells.
 */

import { parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

function splitLine(line) {
  let i = 0
  while (i < line.length && line[i] !== ' ' && line[i] !== '\t') i++
  const address = line.slice(0, i)
  let j = i
  while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
  const content = line.slice(j)
  return [address, content]
}

/**
 * Parse the sheet text into a Map from address key to { content, line }.
 * Throws SheetError on the first invalid address or duplicate declaration.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const [addrRaw, content] = splitLine(stripped)
    const addrUpper = addrRaw.toUpperCase()
    const parsed = parseAddress(addrUpper)
    if (!parsed) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrUpper}`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${addrUpper} is declared twice`)
    }
    cells.set(parsed.key, { content, line: lineNo })
  }
  return cells
}
"}

