export function createEvaluator(cells) {
  const parsed = new Map()
  for (const [key, { content }] of cells) {
    if (content.startsWith('=')) {
      parsed.set(key, { formula: true, ast: parseFormula(content.slice(1)) })
    } else {
      parsed.set(key, { formula: false, value: parseLiteral(content) })
    }
