 * Evaluates every declared cell's content, with cycle detection.
 */

import { parseAddress, makeKey } from './address.js'
import { parseFormula } from './parser.js'
import { num, text, bool, err, toNumber, compareValues, ERROR_TOKENS, ERR_DIV0, ERR_REF, ERR_CYCLE, ERR_NAME, ERR_ERR } from './values.js'

const NUMBER_LITERAL_RE = /^-?\d+(\.\d+)?$/
const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function parseLiteral(content) {
  if (content === '') return num(0)
  if (ERROR_TOKENS.has(content)) return err(content)
  if (NUMBER_LITERAL_RE.test(content)) return num(Number(content))
  return text(content)
}

class CycleSignal {
  constructor(key) {
    this.key = key
  }
}

/**
 * Build an evaluator over the declared cells. `cells` maps address key to
 * { content, line }. Returns { getValue(key), cellAst(key), declaredKeys }.
 */
export function createEvaluator(cells) {
  const parsed = new Map()
  for (const [key, { content }] of cells) {
    if (content.startsWith('=')) {
      parsed.set(key, { formula: true, ast: parseFormula(content.slice(1)) })
    } else {
      parsed.set(key, { formula: false, value: parseLiteral(content) })
    }
  }

  const state = new Map()
  const memo = new Map()

  function resolveAddress(addrText) {
    const addr = parseAddress(addrText)
    if (!addr) return err(ERR_REF)
    return evalKey(addr.key)
  }

  function evalRange(node) {
    const a = parseAddress(node.a)
    const b = parseAddress(node.b)
    if (!a || !b) return [err(ERR_REF)]
    const minCol = Math.min(a.col, b.col)
    const maxCol = Math.max(a.col, b.col)
    const minRow = Math.min(a.row, b.row)
    const maxRow = Math.max(a.row, b.row)
    const out = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) out.push(evalKey(makeKey(c, r)))
    }
    return out
  }

  function evalArgValues(argNode) {
    if (argNode.t === 'range') return evalRange(argNode)
    return [evalNode(argNode)]
  }

  function evalUnary(node) {
    const x = evalNode(node.x)
    const c = toNumber(x)
    if (!c.ok) return c.err
    const v = node.op === '-' ? -c.num : c.num
    if (!Number.isFinite(v)) return err(ERR_DIV0)
    return num(v)
  }

  function evalBin(node) {
    const l = evalNode(node.l)
    const r = evalNode(node.r)
    if (COMPARE_OPS.has(node.op)) {
      if (l.type === 'error') return l
      if (r.type === 'error') return r
      const c = compareValues(l, r)
      switch (node.op) {
        case '=':
          return bool(c === 0)
        case '<>':
          return bool(c !== 0)
        case '<':
          return bool(c < 0)
        case '<=':
          return bool(c <= 0)
        case '>':
          return bool(c > 0)
        case '>=':
          return bool(c >= 0)
      }
    }
    const lc = toNumber(l)
    if (!lc.ok) return lc.err
    const rc = toNumber(r)
    if (!rc.ok) return rc.err
    let v
    switch (node.op) {
      case '+':
        v = lc.num + rc.num
        break
      case '-':
        v = lc.num - rc.num
        break
      case '*':
        v = lc.num * rc.num
        break
      case '/':
        if (rc.num === 0) return err(ERR_DIV0)
        v = lc.num / rc.num
        break
      case '^':
        v = Math.pow(lc.num, rc.num)
        break
    }
    if (!Number.isFinite(v)) return err(ERR_DIV0)
    return num(v)
  }

  function evalCall(node) {
    const { name, args } = node
    if (name === 'IF') {
      if (args.length !== 3) return err(ERR_ERR)
      const condVals = evalArgValues(args[0])
      if (condVals.length !== 1) return err(ERR_ERR)
      const condRead = condVals[0]
      const c = toNumber(condRead)
      if (!c.ok) return c.err
      const branch = c.num !== 0 ? args[1] : args[2]
      const vals = evalArgValues(branch)
      if (vals.length !== 1) return err(ERR_ERR)
      return vals[0]
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err(ERR_ERR)
      const vals = evalArgValues(args[0])
      if (vals.length !== 1) return err(ERR_ERR)
      const c = toNumber(vals[0])
      if (!c.ok) return c.err
      const r = Math.abs(c.num)
      if (!Number.isFinite(r)) return err(ERR_DIV0)
      return num(r)
    }
    if (name === 'SUM' || name === 'MIN' || name === 'MAX' || name === 'COUNT' || name === 'AVG') {
      if (args.length < 1) return err(ERR_ERR)
      const all = []
      for (const a of args) all.push(...evalArgValues(a))
      if (name === 'COUNT') {
        for (const v of all) if (v.type === 'error') return v
        let count = 0
        for (const v of all) if (v.type === 'number') count++
        return num(count)
      }
      const nums = []
      for (const v of all) {
        const c = toNumber(v)
        if (!c.ok) return c.err
        nums.push(c.num)
      }
      let result
      if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
      else if (name === 'MIN') result = Math.min(...nums)
      else if (name === 'MAX') result = Math.max(...nums)
      else result = nums.reduce((a, b) => a + b, 0) / nums.length
      if (!Number.isFinite(result)) return err(ERR_DIV0)
      return num(result)
    }
    return err(ERR_NAME)
  }

  function evalNode(node) {
    switch (node.t) {
      case 'num':
        return num(node.v)
      case 'bool':
        return bool(node.v)
      case 'addr':
        return resolveAddress(node.text)
      case 'un':
        return evalUnary(node)
      case 'bin':
        return evalBin(node)
      case 'call':
        return evalCall(node)
      default:
        throw new Error(`unexpected node type ${node.t}`)
    }
  }

  function evalKey(key) {
    if (memo.has(key)) return memo.get(key)
    if (state.get(key) === 'gray') throw new CycleSignal(key)
    if (!parsed.has(key)) {
      const v = num(0)
      memo.set(key, v)
      return v
    }
    state.set(key, 'gray')
    const cell = parsed.get(key)
    try {
      let value
      if (!cell.formula) value = cell.value
      else if (cell.ast === null) value = err(ERR_ERR)
      else value = evalNode(cell.ast)
      state.set(key, 'black')
      memo.set(key, value)
      return value
    } catch (e) {
      if (e instanceof CycleSignal) {
        state.set(key, 'black')
        const v = err(ERR_CYCLE)
        memo.set(key, v)
        if (e.key !== key) throw e
        return v
      }
      throw e
    }
  }

  return {
    getValue: evalKey,
    cellAst(key) {
      const cell = parsed.get(key)
      return cell && cell.formula ? cell.ast : null
    },
  }
}
