{"file_path":"src/deps.js","content":"/**
 * Purely syntactic dependency extraction: which cells a formula names,
 * independent of whether the call is well-formed or the branch is taken.
 */

import { parseAddress, makeKey } from './address.js'

function visit(node, set) {
  switch (node.t) {
    case 'num':
    case 'bool':
      return
    case 'addr': {
      const a = parseAddress(node.text)
      if (a) set.add(a.key)
      return
    }
    case 'range': {
      const a = parseAddress(node.a)
      const b = parseAddress(node.b)
      if (!a || !b) return
      const minCol = Math.min(a.col, b.col)
      const maxCol = Math.max(a.col, b.col)
      const minRow = Math.min(a.row, b.row)
      const maxRow = Math.max(a.row, b.row)
      for (let c = minCol; c <= maxCol; c++) {
        for (let r = minRow; r <= maxRow; r++) set.add(makeKey(c, r))
      }
      return
    }
    case 'un':
      visit(node.x, set)
      return
    case 'bin':
      visit(node.l, set)
      visit(node.r, set)
      return
    case 'call':
      for (const a of node.args) visit(a, set)
      return
  }
}

/** Returns the set of distinct address keys named directly by a formula AST. */
export function collectDeps(ast) {
  const set = new Set()
  if (ast) visit(ast, set)
  return set
}
"}

