  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  const input = readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
    }
    throw e
  }

  const keys = [...cells.keys()].sort((a, b) => a - b)
  const evaluator = createEvaluator(cells)

  const out = []
  if (mode === 'values') {
    for (const key of keys) {
      const addr = keyToAddress(key)
      const value = evaluator.getValue(key)
      out.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const key of keys) {
      const addr = keyToAddress(key)
      const ast = evaluator.cellAst(key)
      const deps = [...collectDeps(ast)].sort((a, b) => a - b)
      const depsText = deps.map((k) => ` ${keyToAddress(k)}`).join('')
      out.push(`${addr}:${depsText}`)
    }
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

